package com.aac.ieojwo.media;
import com.aac.ieojwo.common.exception.*;import com.aac.ieojwo.user.service.AacUserAccessService;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.*;import org.springframework.security.oauth2.core.oidc.user.OidcUser;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.nio.file.*;import java.util.*;
@Service public class MediaStorageService{public record StoredImage(String url){}private final Path root;private final AacUserAccessService access;private static final Set<String> ALLOWED=Set.of("image/jpeg","image/png","image/webp");public MediaStorageService(@Value("${app.media.upload-dir:./uploads}")String dir,AacUserAccessService access){this.root=Paths.get(dir).toAbsolutePath().normalize();this.access=access;}public StoredImage save(OidcUser p,Long userId,MultipartFile file){access.requireAccessibleUser(p,userId);if(file==null||file.isEmpty())throw new BadRequestException("이미지 파일이 필요합니다.");if(file.getSize()>5*1024*1024)throw new BadRequestException("이미지는 5MB 이하여야 합니다.");if(!ALLOWED.contains(file.getContentType()))throw new BadRequestException("JPEG, PNG, WEBP 이미지만 업로드할 수 있습니다.");String ext=switch(file.getContentType()){case "image/jpeg"->".jpg";case "image/png"->".png";default->".webp";};String name=UUID.randomUUID()+ext;Path dir=root.resolve(userId.toString()).normalize();try{Files.createDirectories(dir);Files.copy(file.getInputStream(),dir.resolve(name),StandardCopyOption.REPLACE_EXISTING);return new StoredImage("/api/v1/me/aac-users/"+userId+"/media/images/"+name);}catch(IOException e){throw new IllegalStateException("이미지 저장에 실패했습니다.",e);}}public Resource load(OidcUser p,Long userId,String name){access.requireAccessibleUser(p,userId);if(!name.matches("[0-9a-fA-F-]+\\.(jpg|png|webp)"))throw new BadRequestException("유효하지 않은 파일명입니다.");Path file=root.resolve(userId.toString()).resolve(name).normalize();if(!file.startsWith(root.resolve(userId.toString()).normalize())||!Files.isRegularFile(file))throw new ResourceNotFoundException("이미지를 찾을 수 없습니다.");return new FileSystemResource(file);}}
